class Test {
    public static int fun(int n, int x) {
        if (n <= 1) {
            return 1;
        }
        x = x + 2;
        return fun(n - 1, x) + x;
    }

    public static void main(String[] args) {
        System.out.println(fun(3, 5));
    }
}

class Test {
    static int sum = 0;

    static int fun(int n) {
        if (n == 0) {
            return 0;
        }
        sum = sum + n;
        return fun(n - 1) + sum;
    }

    public static void main(String[] args) {
        System.out.println(fun(3));
    }
}

